        safe_denominator = tl.where(is_zero, 1.0, 2.0 * magnitude)

        sgn_squared_real = sgn_real * sgn_real - sgn_imag * sgn_imag
        sgn_squared_imag = 2.0 * sgn_real * sgn_imag
